  ProductID INTEGER NOT NULL,
  rowguid UUID NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (SpecialOfferID, ProductID),
  FOREIGN KEY (ProductID) REFERENCES Product (ProductID),
  FOREIGN KEY (SpecialOfferID) REFERENCES SpecialOffer (SpecialOfferID)
);
COMMENT ON TABLE SpecialOfferProduct IS 'AdventureWorks schema: Sales';

CREATE TABLE SalesOrderDetail (
  SalesOrderID INTEGER NOT NULL,
  SalesOrderDetailID INTEGER NOT NULL,
  CarrierTrackingNumber VARCHAR,
  OrderQty SMALLINT NOT NULL,
  ProductID INTEGER NOT NULL,
  SpecialOfferID INTEGER NOT NULL,
  UnitPrice DECIMAL(19,4) NOT NULL,
  UnitPriceDiscount DECIMAL(19,4) NOT NULL,
  LineTotal DECIMAL(38,6),
  rowguid UUID NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (SalesOrderID, SalesOrderDetailID),
  FOREIGN KEY (SalesOrderID) REFERENCES SalesOrderHeader (SalesOrderID),
  FOREIGN KEY (SpecialOfferID, ProductID) REFERENCES SpecialOfferProduct (SpecialOfferID, ProductID)
);
COMMENT ON TABLE SalesOrderDetail IS 'AdventureWorks schema: Sales';

CREATE TABLE SalesReason (
  SalesReasonID INTEGER NOT NULL,
  Name VARCHAR NOT NULL,
  ReasonType VARCHAR NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (SalesReasonID)
);
COMMENT ON TABLE SalesReason IS 'AdventureWorks schema: Sales';

CREATE TABLE SalesOrderHeaderSalesReason (
  SalesOrderID INTEGER NOT NULL,
  SalesReasonID INTEGER NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (SalesOrderID, SalesReasonID),
  FOREIGN KEY (SalesReasonID) REFERENCES SalesReason (SalesReasonID),
  FOREIGN KEY (SalesOrderID) REFERENCES SalesOrderHeader (SalesOrderID)
);
COMMENT ON TABLE SalesOrderHeaderSalesReason IS 'AdventureWorks schema: Sales';

CREATE TABLE SalesPersonQuotaHistory (
  BusinessEntityID INTEGER NOT NULL,
  QuotaDate TIMESTAMP NOT NULL,
  SalesQuota DECIMAL(19,4) NOT NULL,
  rowguid UUID NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (BusinessEntityID, QuotaDate),
  FOREIGN KEY (BusinessEntityID) REFERENCES SalesPerson (BusinessEntityID)
);
COMMENT ON TABLE SalesPersonQuotaHistory IS 'AdventureWorks schema: Sales';

CREATE TABLE SalesTaxRate (
  SalesTaxRateID INTEGER NOT NULL,
  StateProvinceID INTEGER NOT NULL,
  TaxType UTINYINT NOT NULL,
  TaxRate DECIMAL(10,4) NOT NULL,
  Name VARCHAR NOT NULL,
  rowguid UUID NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (SalesTaxRateID),
  FOREIGN KEY (StateProvinceID) REFERENCES StateProvince (StateProvinceID)
);
COMMENT ON TABLE SalesTaxRate IS 'AdventureWorks schema: Sales';

CREATE TABLE SalesTerritoryHistory (
  BusinessEntityID INTEGER NOT NULL,
  TerritoryID INTEGER NOT NULL,
  StartDate TIMESTAMP NOT NULL,
  EndDate TIMESTAMP,
  rowguid UUID NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (BusinessEntityID, StartDate, TerritoryID),
  FOREIGN KEY (BusinessEntityID) REFERENCES SalesPerson (BusinessEntityID),
  FOREIGN KEY (TerritoryID) REFERENCES SalesTerritory (TerritoryID)
);
COMMENT ON TABLE SalesTerritoryHistory IS 'AdventureWorks schema: Sales';

CREATE TABLE ScrapReason (
  ScrapReasonID SMALLINT NOT NULL,
  Name VARCHAR NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (ScrapReasonID)
);
COMMENT ON TABLE ScrapReason IS 'AdventureWorks schema: Production';

CREATE TABLE ShoppingCartItem (
  ShoppingCartItemID INTEGER NOT NULL,
  ShoppingCartID VARCHAR NOT NULL,
  Quantity INTEGER NOT NULL,
  ProductID INTEGER NOT NULL,
  DateCreated TIMESTAMP NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (ShoppingCartItemID),
  FOREIGN KEY (ProductID) REFERENCES Product (ProductID)
);
COMMENT ON TABLE ShoppingCartItem IS 'AdventureWorks schema: Sales';

CREATE TABLE TransactionHistory (
  TransactionID INTEGER NOT NULL,
  ProductID INTEGER NOT NULL,
  ReferenceOrderID INTEGER NOT NULL,
  ReferenceOrderLineID INTEGER NOT NULL,
  TransactionDate TIMESTAMP NOT NULL,
  TransactionType VARCHAR NOT NULL,
  Quantity INTEGER NOT NULL,
  ActualCost DECIMAL(19,4) NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (TransactionID),
  FOREIGN KEY (ProductID) REFERENCES Product (ProductID)
);
COMMENT ON TABLE TransactionHistory IS 'AdventureWorks schema: Production';

CREATE TABLE TransactionHistoryArchive (
  TransactionID INTEGER NOT NULL,
  ProductID INTEGER NOT NULL,
  ReferenceOrderID INTEGER NOT NULL,
  ReferenceOrderLineID INTEGER NOT NULL,
  TransactionDate TIMESTAMP NOT NULL,
  TransactionType VARCHAR NOT NULL,
  Quantity INTEGER NOT NULL,
  ActualCost DECIMAL(19,4) NOT NULL,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (TransactionID)
);
COMMENT ON TABLE TransactionHistoryArchive IS 'AdventureWorks schema: Production';

CREATE TABLE WorkOrder (
  WorkOrderID INTEGER NOT NULL,
  ProductID INTEGER NOT NULL,
  OrderQty INTEGER NOT NULL,
  StockedQty INTEGER,
  ScrappedQty SMALLINT NOT NULL,
  StartDate TIMESTAMP NOT NULL,
  EndDate TIMESTAMP,
  DueDate TIMESTAMP NOT NULL,
  ScrapReasonID SMALLINT,
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (WorkOrderID),
  FOREIGN KEY (ProductID) REFERENCES Product (ProductID),
  FOREIGN KEY (ScrapReasonID) REFERENCES ScrapReason (ScrapReasonID)
);
COMMENT ON TABLE WorkOrder IS 'AdventureWorks schema: Production';

CREATE TABLE WorkOrderRouting (
  WorkOrderID INTEGER NOT NULL,
  ProductID INTEGER NOT NULL,
  OperationSequence SMALLINT NOT NULL,
  LocationID SMALLINT NOT NULL,
  ScheduledStartDate TIMESTAMP NOT NULL,
  ScheduledEndDate TIMESTAMP NOT NULL,
  ActualStartDate TIMESTAMP,
  ActualEndDate TIMESTAMP,
  ActualResourceHrs DECIMAL(9, 4),
  PlannedCost DECIMAL(19,4) NOT NULL,
  ActualCost DECIMAL(19,4),
  ModifiedDate TIMESTAMP NOT NULL,
  PRIMARY KEY (WorkOrderID, ProductID, OperationSequence),
  FOREIGN KEY (LocationID) REFERENCES Location (LocationID),
  FOREIGN KEY (WorkOrderID) REFERENCES WorkOrder (WorkOrderID)
);
COMMENT ON TABLE WorkOrderRouting IS 'AdventureWorks schema: Production';
